-- GummyBearing v9: original mock seed, 27 rows. No live DB export.
-- Run 01_schema.sql first on a NEW LOCAL practice database (MySQL 8.4).
-- UTF-8 hex literals follow the v9 exporter to preserve Korean text in every client.
-- Readable data is in mock_source/*.json. Login/account/session rows are excluded.
-- The helper refuses a non-empty database and rolls back on any insert error.
SET NAMES utf8mb4;
USE `gummybearing_v5_draft`;
DROP PROCEDURE IF EXISTS `gb_share_v9_import_mock`;
DELIMITER $$
CREATE PROCEDURE `gb_share_v9_import_mock`()
BEGIN
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  START TRANSACTION;
  IF EXISTS (SELECT 1 FROM `equipment` LIMIT 1)
     OR EXISTS (SELECT 1 FROM `inspections` LIMIT 1)
     OR EXISTS (SELECT 1 FROM `maintenance_reviews` LIMIT 1)
     OR EXISTS (SELECT 1 FROM `follow_ups` LIMIT 1)
     OR EXISTS (SELECT 1 FROM `work_history` LIMIT 1)
     OR EXISTS (SELECT 1 FROM `gb_users` LIMIT 1)
     OR EXISTS (SELECT 1 FROM `gb_sessions` LIMIT 1)
     OR EXISTS (SELECT 1 FROM `gb_login_attempts` LIMIT 1)
     OR EXISTS (SELECT 1 FROM `gb_inspection_authors` LIMIT 1)
     OR EXISTS (SELECT 1 FROM `gb_followup_completions` LIMIT 1)
     OR EXISTS (SELECT 1 FROM `gb_followup_authors` LIMIT 1) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Use an empty practice database; existing data was not changed.';
  END IF;
